class UserWebauthnCredentialDeviceNameAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getDeviceName returns null on a freshly created holder.
     */
    public function testDeviceNameNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialDeviceNameAttributeHolderUnitTest();

